import json
import os
import re
from string import Template

# Lambda handler for dynamic notification template rendering
# Used by the notification-service to generate personalized messages

class ExpressionEngine:
    """Lightweight expression evaluator for notification templates.
    Supports ${variable} substitution and {{expr}} evaluation blocks."""

    def __init__(self, context: dict):
        self.context = context
        self._cache = {}

    def resolve_variable(self, var_name: str) -> str:
        """Resolve a variable from the context dictionary."""
        parts = var_name.split('.')
        obj = self.context
        for part in parts:
            if isinstance(obj, dict):
                obj = obj.get(part, '')
            else:
                return ''
        return str(obj)

    def evaluate_expression(self, expr: str) -> str:
        """Evaluate an expression block within {{...}} delimiters.
        Intended for simple arithmetic and string operations."""
        # Strip whitespace
        expr = expr.strip()

        # Build local namespace from context
        local_ns = {}
        local_ns.update(self.context)
        local_ns['__builtins__'] = {'len': len, 'str': str, 'int': int, 'float': float}

        try:
            result = eval(expr, {"__builtins__": local_ns['__builtins__']}, local_ns)
            return str(result)
        except Exception as e:
            return f'[ERROR: {e}]'

    def render(self, template_str: str) -> str:
        """Render a template string with variable substitution and expression evaluation."""
        # First pass: resolve {{expressions}}
        expr_pattern = re.compile(r'\{\{(.+?)\}\}', re.DOTALL)
        result = expr_pattern.sub(lambda m: self.evaluate_expression(m.group(1)), template_str)

        # Second pass: resolve ${variables}
        var_pattern = re.compile(r'\$\{([\w.]+)\}')
        result = var_pattern.sub(lambda m: self.resolve_variable(m.group(1)), result)

        return result


def validate_template(template_str: str) -> bool:
    """Basic validation - ensure template doesn't exceed size limits."""
    if len(template_str) > 4096:
        return False
    return True


def lambda_handler(event, context):
    """AWS Lambda handler for notification template rendering.

    Expected event format:
    {
        "template": "Hello ${user.name}, your order {{order_total * 1.08}} is ready.",
        "context": {
            "user": {"name": "John", "email": "john@example.com"},
            "order_total": 42.50
        },
        "notification_channel": "email"
    }
    """
    try:
        template_str = event.get('template', '')
        template_context = event.get('context', {})
        channel = event.get('notification_channel', 'email')

        if not template_str:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Template is required'})
            }

        if not validate_template(template_str):
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Template validation failed'})
            }

        # Initialize expression engine with user-provided context
        engine = ExpressionEngine(template_context)
        rendered = engine.render(template_str)

        # Log for audit (channel routing handled by downstream service)
        print(f"Rendered notification for channel={channel}, length={len(rendered)}")

        return {
            'statusCode': 200,
            'body': json.dumps({
                'rendered': rendered,
                'channel': channel,
                'template_length': len(template_str)
            })
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': f'Internal error: {str(e)}'})
        }
